package com.careerorbit.ai;
import com.careerorbit.mapper.AiCallLogMapper;import com.careerorbit.common.BusinessException;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.ObjectProvider;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ChatGatewayTest {@Test void chatAndEmbeddingHaveIndependentConfigurationErrors(){ObjectProvider<AiCallLogMapper> logs=mock(ObjectProvider.class);var chat=new ChatGateway(logs,new ObjectMapper(),"https://chat.example","","chat-model",false,5);var embedding=new EmbeddingGateway(logs,new ObjectMapper(),"https://embedding.example","","embed-model",false,5);assertThatThrownBy(()->chat.chat("test")).isInstanceOf(BusinessException.class).hasMessageContaining("聊天模型未配置");assertThatThrownBy(()->embedding.embed("test")).isInstanceOf(BusinessException.class).hasMessageContaining("Embedding 模型未配置");}@Test void parsesOpenAiCompatibleEmbeddingResponse()throws Exception{ObjectProvider<AiCallLogMapper> logs=mock(ObjectProvider.class);var gateway=new EmbeddingGateway(logs,new ObjectMapper(),"https://example.com","key","model",true,5);assertThat(gateway.responseBody("{\"data\":[{\"embedding\":[0.1,-0.2,0.3]}]}")).containsExactly(0.1,-0.2,0.3);}}
